export const language=()=>globalThis.satinLanguageOverride||(/^\/satin\/(fa|fr|es)(?=\/|$)/.exec(location.pathname)?.[1]||'en');
export function t(s){const v=String(s??''),key=v.trim(),lang=language();if(lang==='en')return v;const translated=DICT[key]?.[lang]||globalThis.satinTranslate?.(key);if(translated&&translated!==key)return v.replace(key,translated);if(/^\d/.test(key)&&/\bin\b|\bft\b/.test(key))return v.replace(/\bin trim\b/g,lang==='fa'?'اینچ اندازه نهایی':lang==='fr'?'po format final':'pulg. finales').replace(/\bin bleed\b/g,lang==='fa'?'اینچ بلید':lang==='fr'?'po fond perdu':'pulg. de sangrado').replace(/\bin\b/g,lang==='fa'?'اینچ':lang==='fr'?'po':'pulg.').replace(/\bft\b/g,lang==='fa'?'فوت':lang==='fr'?'pi':'pies').replace('Flat print',lang==='fa'?'چاپ تخت':lang==='fr'?'Impression à plat':'Impresión plana');return v;}
export const localizedPath=path=>path.replace(/^\/satin(?:\/(fa|fr|es))?(?=\/|$)/,'/satin'+(language()==='en'?'':'/'+language()))+'/';
export function translateTree(root){if(!root||language()==='en')return;const walker=document.createTreeWalker(root,NodeFilter.SHOW_TEXT);let n;while(n=walker.nextNode()){if(n.parentElement&&!n.parentElement.closest('script,style,svg,textarea,[data-no-translate]')){const next=t(n.textContent);if(next!==n.textContent)n.textContent=next;}}root.querySelectorAll('[aria-label],[placeholder],img[alt]').forEach(el=>{for(const k of ['aria-label','placeholder','alt'])if(el.hasAttribute(k)){const old=el.getAttribute(k),next=t(old);if(old!==next)el.setAttribute(k,next);}});}
export function observeTranslations(root){translateTree(root);let pending=false;const observer=new MutationObserver(()=>{if(pending)return;pending=true;queueMicrotask(()=>{pending=false;observer.disconnect();translateTree(root);observer.observe(root,{childList:true,subtree:true,characterData:true});});});observer.observe(root,{childList:true,subtree:true,characterData:true});return ()=>observer.disconnect();}

export function registerRuleTranslations(rule){for(const f of [rule,...rule.fields||[]]){if(f.translations)DICT[f.label]={...DICT[f.label],...f.translations};for(const o of f.options||[])if(o.translations)DICT[o.label]={...DICT[o.label],...o.translations};}}

