for(const [k,v] of Object.entries({"Save this design to your account": {"fa": "ذخیرهٔ این طرح در حساب شما", "fr": "Enregistrer ce design dans votre compte", "es": "Guardar este diseño en tu cuenta"}, "Sign in or create a free account to keep this design in My account → Saved designs. You can download it, edit it and order it any time. It also stays in this browser for 30 days.": {"fa": "برای نگه‌داشتن این طرح در «حساب من ← طرح‌های ذخیره‌شده» وارد شوید یا یک حساب رایگان بسازید. هر زمان می‌توانید آن را دانلود، ویرایش و سفارش دهید. این طرح ۳۰ روز در همین مرورگر هم می‌ماند.", "fr": "Connectez-vous ou créez un compte gratuit pour garder ce design dans Mon compte → Designs enregistrés. Vous pourrez le télécharger, le modifier et le commander à tout moment. Il reste aussi 30 jours dans ce navigateur.", "es": "Inicia sesión o crea una cuenta gratuita para guardar este diseño en Mi cuenta → Diseños guardados. Podrás descargarlo, editarlo y pedirlo cuando quieras. También queda 30 días en este navegador."}, "Sign in": {"fa": "ورود", "fr": "Se connecter", "es": "Iniciar sesión"}, "Create account": {"fa": "ساخت حساب", "fr": "Créer un compte", "es": "Crear cuenta"}, "Keep in this browser only": {"fa": "فقط در همین مرورگر بماند", "fr": "Garder dans ce navigateur seulement", "es": "Solo en este navegador"}, "Saved in this browser for 30 days.": {"fa": "تا ۳۰ روز در این مرورگر ذخیره شد.", "fr": "Enregistré dans ce navigateur pour 30 jours.", "es": "Guardado en este navegador durante 30 días."}, "Saving to your account…": {"fa": "در حال ذخیره در حساب شما…", "fr": "Enregistrement dans votre compte…", "es": "Guardando en tu cuenta…"}, "Saved to your account (My account → Saved designs).": {"fa": "در حساب شما ذخیره شد (حساب من ← طرح‌های ذخیره‌شده).", "fr": "Enregistré dans votre compte (Mon compte → Designs enregistrés).", "es": "Guardado en tu cuenta (Mi cuenta → Diseños guardados)."}, "Drafts stay in this browser for 30 days. Use Save to keep a design in your account (My account → Saved designs).": {"fa": "پیش‌نویس‌ها ۳۰ روز در این مرورگر می‌مانند. برای نگه‌داشتن طرح در حساب خود «ذخیره» را بزنید (حساب من ← طرح‌های ذخیره‌شده).", "fr": "Les brouillons restent 30 jours dans ce navigateur. Utilisez Enregistrer pour garder un design dans votre compte (Mon compte → Designs enregistrés).", "es": "Los borradores quedan 30 días en este navegador. Usa Guardar para conservar un diseño en tu cuenta (Mi cuenta → Diseños guardados)."}, "Your design": {"fa": "طرح شما", "fr": "Votre design", "es": "Tu diseño"}, "Front and back": {"fa": "جلو و پشت", "fr": "Devant et dos", "es": "Frente y espalda"}, "As approved in Design Studio": {"fa": "همان‌طور که در استودیو طراحی تأیید شد", "fr": "Tel qu’approuvé dans le Studio", "es": "Tal como se aprobó en el Estudio"}, "Edit design": {"fa": "ویرایش طرح", "fr": "Modifier le design", "es": "Editar diseño"}, "Mockup of your approved design": {"fa": "ماکاپ طرح تأییدشدهٔ شما", "fr": "Aperçu de votre design approuvé", "es": "Maqueta de tu diseño aprobado"}, "Front": {"fa": "جلو", "fr": "Devant", "es": "Frente"}, "Back": {"fa": "پشت", "fr": "Dos", "es": "Espalda"}}))if(!DICT[k])DICT[k]=v;

