for(const [k,v] of Object.entries({"Templates": {"fa": "قالب‌ها", "fr": "Modèles", "es": "Plantillas"}, "Professional layouts sized for this product. Every element stays editable.": {"fa": "طرح‌های حرفه‌ای در اندازهٔ همین محصول. همهٔ اجزا قابل ویرایش هستند.", "fr": "Mises en page professionnelles adaptées à ce produit. Chaque élément reste modifiable.", "es": "Diseños profesionales a la medida de este producto. Todo sigue siendo editable."}, "Search templates": {"fa": "جستجوی قالب", "fr": "Rechercher un modèle", "es": "Buscar plantillas"}, "No templates match your search.": {"fa": "قالبی با این جستجو پیدا نشد.", "fr": "Aucun modèle ne correspond à votre recherche.", "es": "Ninguna plantilla coincide con tu búsqueda."}, "All": {"fa": "همه", "fr": "Tous", "es": "Todas"}, "Automotive": {"fa": "خودرو", "fr": "Automobile", "es": "Automotriz"}, "Real estate": {"fa": "املاک", "fr": "Immobilier", "es": "Bienes raíces"}, "Restaurant & café": {"fa": "رستوران و کافه", "fr": "Restaurant et café", "es": "Restaurante y café"}, "Construction & trades": {"fa": "ساختمان و پیمانکاری", "fr": "Construction et métiers", "es": "Construcción y oficios"}, "Home services": {"fa": "خدمات منزل", "fr": "Services à domicile", "es": "Servicios del hogar"}, "Beauty & salon": {"fa": "زیبایی و سالن", "fr": "Beauté et salon", "es": "Belleza y salón"}, "Medical & dental": {"fa": "پزشکی و دندان‌پزشکی", "fr": "Médical et dentaire", "es": "Médico y dental"}, "Fitness": {"fa": "ورزش", "fr": "Mise en forme", "es": "Fitness"}, "Retail & sale": {"fa": "فروشگاه و حراج", "fr": "Commerce et soldes", "es": "Tiendas y ofertas"}, "Events": {"fa": "رویدادها", "fr": "Événements", "es": "Eventos"}, "Corporate": {"fa": "شرکتی", "fr": "Entreprise", "es": "Corporativo"}, "Minimal": {"fa": "مینیمال", "fr": "Minimaliste", "es": "Minimalista"}, "Bold": {"fa": "پررنگ", "fr": "Audacieux", "es": "Llamativo"}, "Use this template?": {"fa": "از این قالب استفاده شود؟", "fr": "Utiliser ce modèle ?", "es": "¿Usar esta plantilla?"}, "Replace the design on this side, or add the template on top of it? You can undo either with Ctrl+Z.": {"fa": "طرح این رو جایگزین شود یا قالب روی آن اضافه شود؟ با Ctrl+Z می‌توانید برگردید.", "fr": "Remplacer le design de ce côté ou ajouter le modèle par-dessus ? Vous pouvez annuler avec Ctrl+Z.", "es": "¿Reemplazar el diseño de este lado o añadir la plantilla encima? Puedes deshacer con Ctrl+Z."}, "Replace this side": {"fa": "جایگزینی این رو", "fr": "Remplacer ce côté", "es": "Reemplazar este lado"}, "Add on top": {"fa": "افزودن روی طرح", "fr": "Ajouter par-dessus", "es": "Añadir encima"}, "Template added. Double-click any text to change it.": {"fa": "قالب اضافه شد. برای تغییر متن روی آن دوبار کلیک کنید.", "fr": "Modèle ajouté. Double-cliquez sur un texte pour le modifier.", "es": "Plantilla añadida. Haz doble clic en un texto para cambiarlo."}, "Template added to the front and back. Double-click any text to change it.": {"fa": "قالب به جلو و پشت اضافه شد. برای تغییر متن روی آن دوبار کلیک کنید.", "fr": "Modèle ajouté au recto et au verso. Double-cliquez sur un texte pour le modifier.", "es": "Plantilla añadida al frente y al reverso. Haz doble clic en un texto para cambiarlo."}, "Gradient": {"fa": "گرادیان", "fr": "Dégradé", "es": "Degradado"}, "No gradient": {"fa": "بدون گرادیان", "fr": "Sans dégradé", "es": "Sin degradado"}, "Gradient end colour": {"fa": "رنگ پایان گرادیان", "fr": "Couleur de fin du dégradé", "es": "Color final del degradado"}, "Icons": {"fa": "آیکون‌ها", "fr": "Icônes", "es": "Iconos"}, "Shapes & decorations": {"fa": "شکل‌ها و تزئینات", "fr": "Formes et décorations", "es": "Formas y decoraciones"}, "Your design was not submitted.": {"fa": "طرح شما ارسال نشد.", "fr": "Votre design n’a pas été envoyé.", "es": "Tu diseño no se envió."}, "Nothing was lost — your design is saved. Try Submit design again, or use Download PDF and email the file to info@satingraphic.ca.": {"fa": "چیزی از دست نرفته و طرح شما ذخیره است. دوباره «ارسال طرح» را بزنید یا PDF را دانلود و به info@satingraphic.ca ایمیل کنید.", "fr": "Rien n’est perdu : votre design est enregistré. Réessayez « Envoyer le design » ou téléchargez le PDF et envoyez-le à info@satingraphic.ca.", "es": "No se perdió nada: tu diseño está guardado. Vuelve a intentar «Enviar diseño» o descarga el PDF y envíalo a info@satingraphic.ca."}, "Your design is too large to send. Use smaller images, or use Download PDF and email it to info@satingraphic.ca.": {"fa": "طرح شما برای ارسال بیش از حد بزرگ است. از تصاویر کوچک‌تر استفاده کنید یا PDF را دانلود و به info@satingraphic.ca ایمیل کنید.", "fr": "Votre design est trop volumineux. Utilisez des images plus petites ou téléchargez le PDF et envoyez-le à info@satingraphic.ca.", "es": "Tu diseño es demasiado grande. Usa imágenes más pequeñas o descarga el PDF y envíalo a info@satingraphic.ca."}, "The server sent an unexpected reply. Please try again.": {"fa": "پاسخ سرور غیرمنتظره بود. لطفاً دوباره تلاش کنید.", "fr": "Réponse inattendue du serveur. Veuillez réessayer.", "es": "Respuesta inesperada del servidor. Inténtalo de nuevo."}, "Download PDF saves a print-ready file (trim size plus bleed; up to 300 DPI, large formats at a resolution suited to their viewing distance).": {"fa": "«دانلود PDF» فایل آمادهٔ چاپ را ذخیره می‌کند (اندازهٔ برش به‌همراه بلید؛ تا ۳۰۰ DPI و برای چاپ‌های بزرگ با وضوح مناسب فاصلهٔ دید).", "fr": "« Télécharger le PDF » enregistre un fichier prêt à imprimer (format fini plus fond perdu ; jusqu’à 300 DPI, grands formats à une résolution adaptée à la distance de lecture).", "es": "«Descargar PDF» guarda un archivo listo para imprimir (tamaño final más sangrado; hasta 300 DPI, gran formato a la resolución adecuada para su distancia de visión)."}}))if(!DICT[k])DICT[k]=v;
